export const WhiteboardV1ElementSchema = Schema.Unknown.check(Schema.makeFilter((value) => (isElement(value) ? undefined : { path: [], issue: "must be a strict bounded whiteboard-v1 element" }))).pipe(Schema.decodeTo(Schema.declare((value): value is WhiteboardV1Element => isElement(value))));
export const WhiteboardV1ClientFrameSchema = Schema.Unknown.check(
  Schema.makeFilter((value) => (isClientFrame(value) && encodedWhiteboardV1FrameBytes(value) <= WhiteboardV1ProtocolLimits.decodedInboundFrameBytes ? undefined : { path: [], issue: "must be a strict bounded whiteboard-v1 client frame" })),
).pipe(Schema.decodeTo(Schema.declare((value): value is WhiteboardV1ClientFrame => isClientFrame(value))));
export const WhiteboardV1ServerFrameSchema = Schema.Unknown.check(
  Schema.makeFilter((value) => (isServerFrame(value) && encodedWhiteboardV1FrameBytes(value) <= WhiteboardV1ProtocolLimits.encodedOutboundFrameBytes ? undefined : { path: [], issue: "must be a strict bounded whiteboard-v1 server frame" })),
).pipe(Schema.decodeTo(Schema.declare((value): value is WhiteboardV1ServerFrame => isServerFrame(value))));

export function encodeWhiteboardV1Frame(frame: WhiteboardV1ClientFrame | WhiteboardV1ServerFrame): string {
  return JSON.stringify(frame);
}
